// Generate HTML Email — LstVGNews tabellformat med LST grafisk profil.
// Tar AI-genererad <table> och wrappar den i ett stilat mailskal.
// Returnerar { html, subject }.

const tableHtml = $json.choices[0].message.content || '';
const now = new Date().toLocaleString('sv-SE');

const C = {
  primary: '#004B87',
  gold: '#E4B363',
  bg: '#EAEEF2',
  white: '#FFFFFF',
  text: '#1a1a1a',
  textLight: 'rgba(255,255,255,0.55)',
  border: '#E0E0E0',
  headerCell: '#003D72',
  rowAlt: '#F0F4F8',
};

const tableStyle = `
  border-collapse: collapse;
  width: 100%;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 13px;
  color: ${C.text};
`;

const thStyle = `
  background-color: ${C.headerCell};
  color: #FFFFFF;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 11px;
  letter-spacing: 1px;
  text-transform: uppercase;
  padding: 10px 14px;
  text-align: left;
  border: none;
`;

const tdStyle = `
  padding: 10px 14px;
  vertical-align: top;
  border-bottom: 1px solid ${C.border};
  font-family: Arial, Helvetica, sans-serif;
  font-size: 13px;
  color: ${C.text};
  line-height: 1.5;
`;

// Injicera inline-stilar i AI:ns tabell-markup.
let styledTable = tableHtml
  .replace(/<table[^>]*>/gi, `<table style="${tableStyle.replace(/\n\s*/g, ' ').trim()}">`)
  .replace(/<th([^>]*)>/gi, `<th$1 style="${thStyle.replace(/\n\s*/g, ' ').trim()}">`)
  .replace(/<td([^>]*)>/gi, `<td$1 style="${tdStyle.replace(/\n\s*/g, ' ').trim()}">`);

const html = `<!DOCTYPE html>
<html lang="sv" xmlns="http://www.w3.org/1999/xhtml">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>LstVGNews</title></head>
<body style="margin:0;padding:0;background-color:${C.bg};font-family:Arial,Helvetica,sans-serif;">
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background-color:${C.bg};">
  <tr><td align="center" style="padding:24px 12px;">
  <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="700" style="max-width:700px;width:100%;background-color:${C.white};">

    <!-- HEADER -->
    <tr><td style="background-color:${C.primary};padding:0;">
      <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">
        <tr><td style="height:4px;background-color:${C.gold};font-size:1px;line-height:1px;">&nbsp;</td></tr>
      </table>
      <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">
        <tr><td style="padding:28px 36px 6px 36px;">
          <span style="font-family:Georgia,serif;font-size:11px;letter-spacing:2.5px;text-transform:uppercase;color:${C.gold};">Länsstyrelsen Västra Götaland</span>
        </td></tr>
        <tr><td style="padding:0 36px 8px 36px;">
          <span style="font-family:Georgia,serif;font-size:26px;font-weight:bold;color:${C.white};">LstVGNews</span>
          <span style="font-family:Georgia,serif;font-size:26px;color:rgba(255,255,255,0.45);"> — </span>
          <span style="font-family:Georgia,serif;font-size:26px;font-style:italic;color:rgba(255,255,255,0.8);">24h High</span>
        </td></tr>
        <tr><td style="padding:0 36px 24px 36px;">
          <span style="font-family:Arial,sans-serif;font-size:13px;color:${C.textLight};">${now}</span>
        </td></tr>
      </table>
    </td></tr>

    <!-- TABELL -->
    <tr><td style="padding:32px 36px;">
      ${styledTable}
    </td></tr>

    <!-- FOOTER -->
    <tr><td style="background-color:${C.primary};padding:0;">
      <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">
        <tr><td style="height:3px;background-color:${C.gold};font-size:1px;line-height:1px;">&nbsp;</td></tr>
      </table>
      <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">
        <tr><td style="padding:18px 36px;">
          <p style="font-family:Arial,sans-serif;font-size:11px;color:rgba(255,255,255,0.5);margin:0;">AI-genererad sammanfattning — verifiera mot primärkälla före vidare spridning. &nbsp;·&nbsp; LstVGNews · ${now}</p>
        </td></tr>
      </table>
    </td></tr>

  </table>
  </td></tr>
</table>
</body>
</html>`;

return [{ json: { html, subject: `LstVGNews - 24h High ${new Date().toLocaleDateString('sv-SE')}` } }];
